//! Gold: `family_device_matrix` is 1:1 with the live reference.
//!
//! `tests/fixtures/gold/family_device_matrix_v1.json` was generated by
//! `scripts/gold_family_device_matrix.py` — census cases render a real PDF and
//! run the reference's own `extract_family_matrix` end to end (with the live
//! `family_census.census_document` row as its input), kernel cases call the
//! reference's pure readers. The inputs the port consumes travel in the gold
//! (table grids as `extract()` returns them, cell boxes and page words for
//! geometry binding) so this replays identical input. The volatile `_meta`
//! keys are stripped.
//!
//! The cases pin the traps the reader exists for: the strict label grammar
//! ("GPIOs" is gpio_count not pin_count, "Tamper pins" is nothing, "Maximum
//! CPU frequency" is freq_mhz not core), the code-flash/data-flash and
//! sram/backup look-alike exclusions, composite rows ("SPI / I2S : 4/3"
//! splits because the document printed the pairing), header binding cases
//! (newline-split tokens, stem+code lists, wildcard joins through a printed
//! device summary, ordering-suffix variants stay unbound), merged cells
//! flagged as merged, alternatives staying unknown, qualified numbers keeping
//! their printed words, the ST memory-letter self-check, and bit-width group
//! sums.

#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::indexing_slicing,
    clippy::too_many_lines,
    clippy::cast_possible_truncation,
    clippy::doc_markdown,
    reason = "gold tests assert on their own fixtures"
)]

use std::collections::BTreeMap;
use std::path::PathBuf;

use dw_recon::family_device_matrix::{
    bind_columns, cell_leaves, extract_family_matrix, header_token, parse_value, read_matrix_table,
    row_attributes, split_composite_label, split_composite_value, split_glued_runs,
    st_flash_code_kb, MatrixGrid, MatrixInput, Word,
};

fn gold_path() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    while !dir.join("tests/fixtures/gold").is_dir() {
        assert!(dir.pop(), "could not locate tests/fixtures/gold");
    }
    dir.join("tests/fixtures/gold/family_device_matrix_v1.json")
}

fn gold() -> serde_json::Value {
    serde_json::from_str(&std::fs::read_to_string(gold_path()).unwrap()).unwrap()
}

/// One matrix candidate with its geometry, owned so `MatrixGrid` can borrow it.
struct OwnedGrid {
    page: usize,
    rows: Vec<Vec<Option<String>>>,
    words: Vec<Word>,
    cells: Vec<[f64; 4]>,
    header_cells: Vec<[f64; 4]>,
}

fn summary_tables_of(v: &serde_json::Value) -> Vec<(usize, Vec<Vec<Option<String>>>)> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|e| {
            let page = e["page"].as_u64().unwrap() as usize;
            let rows: Vec<Vec<Option<String>>> = serde_json::from_value(e["rows"].clone()).unwrap();
            (page, rows)
        })
        .collect()
}

fn grids_of(v: &serde_json::Value) -> Vec<OwnedGrid> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|e| OwnedGrid {
            page: e["page"].as_u64().unwrap() as usize,
            rows: serde_json::from_value(e["rows"].clone()).unwrap(),
            words: serde_json::from_value(e["words"].clone()).unwrap(),
            cells: serde_json::from_value(e["cells"].clone()).unwrap(),
            header_cells: serde_json::from_value(e["header_cells"].clone()).unwrap(),
        })
        .collect()
}

#[test]
fn every_case_matches_the_live_reference() {
    let g = gold();
    let mut checked = 0;
    for case in g["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let got: serde_json::Value = match case["kind"].as_str().unwrap() {
            "census" => {
                let input = &case["input"];
                let summary_tables = summary_tables_of(&input["summary_tables"]);
                let owned = grids_of(&input["matrices"]);
                let grids: Vec<MatrixGrid<'_>> = owned
                    .iter()
                    .map(|m| MatrixGrid {
                        page: m.page,
                        rows: &m.rows,
                        words: &m.words,
                        cells: &m.cells,
                        header_cells: &m.header_cells,
                    })
                    .collect();
                let doc = MatrixInput {
                    summary_tables: &summary_tables,
                    matrices: &grids,
                    census_row: &case["census_row"],
                    document_sha256: case["document_sha256"].as_str().unwrap(),
                };
                let mut got = extract_family_matrix(&doc);
                let meta = got.get_mut("_meta").unwrap().as_object_mut().unwrap();
                for k in ["extracted_at", "document_sha256", "source_path"] {
                    meta.remove(k);
                }
                got
            }
            "parse_value" => serde_json::to_value(parse_value(
                case["verbatim"].as_str().unwrap(),
                case["attribute"].as_str().unwrap(),
                case["label_unit"].as_str(),
            ))
            .unwrap(),
            "row_attributes" => serde_json::to_value(row_attributes(
                case["group_label"].as_str().unwrap(),
                case["sub_label"].as_str().unwrap(),
            ))
            .unwrap(),
            "split_composite_label" => {
                serde_json::to_value(split_composite_label(case["sub_label"].as_str().unwrap()))
                    .unwrap()
            }
            "split_composite_value" => serde_json::to_value(split_composite_value(
                case["text"].as_str().unwrap(),
                case["count"].as_u64().unwrap() as usize,
            ))
            .unwrap(),
            "header_token" => {
                serde_json::to_value(header_token(case["cell"].as_str().unwrap())).unwrap()
            }
            "split_glued_runs" => {
                let values: Vec<(String, bool)> =
                    serde_json::from_value(case["values"].clone()).unwrap();
                serde_json::to_value(split_glued_runs(&values)).unwrap()
            }
            "st_flash_code_kb" => serde_json::to_value(st_flash_code_kb(Some(
                case["part_number"].as_str().unwrap(),
            )))
            .unwrap(),
            "bind_columns" => {
                let grid: Vec<Vec<String>> = serde_json::from_value(case["grid"].clone()).unwrap();
                let label_cols = case["label_cols"].as_u64().unwrap() as usize;
                let summary: BTreeMap<String, Vec<String>> =
                    serde_json::from_value(case["device_summary"].clone()).unwrap();
                let parts: Option<Vec<String>> =
                    serde_json::from_value(case["parts_named"].clone()).unwrap();
                serde_json::to_value(bind_columns(&grid, label_cols, &summary, parts.as_deref()))
                    .unwrap()
            }
            "read_matrix_table" => {
                let rows: Vec<Vec<Option<String>>> =
                    serde_json::from_value(case["rows"].clone()).unwrap();
                let page = case["page"].as_u64().unwrap() as usize;
                let summary: BTreeMap<String, Vec<String>> =
                    serde_json::from_value(case["device_summary"].clone()).unwrap();
                let parts: Option<Vec<String>> =
                    serde_json::from_value(case["parts_named"].clone()).unwrap();
                serde_json::to_value(read_matrix_table(
                    &rows,
                    page,
                    &summary,
                    None,
                    None,
                    None,
                    parts.as_deref(),
                ))
                .unwrap()
            }
            "cell_leaves" => {
                let attributes: Vec<(String, Option<usize>)> =
                    serde_json::from_value(case["attributes"].clone()).unwrap();
                serde_json::to_value(cell_leaves(
                    case["verbatim"].as_str().unwrap(),
                    &attributes,
                    case["label_unit"].as_str(),
                    case["label_components"].as_u64().map(|n| n as usize),
                ))
                .unwrap()
            }
            other => panic!("unknown gold case kind {other}"),
        };
        assert_eq!(got, case["expected"], "case {name}");
        checked += 1;
    }
    assert_eq!(checked, g["cases"].as_array().unwrap().len());
}
